int search ( int A[], int n, int key ) {
  int b = 0;
  while ( n > 1 ) {
    int h = n / 2;
    int t = A[b+h];
    b = (t < key) ? b+h : b;
    n = n - h;
  }
  return b;
}

int search ( int A[], int n, int key ) {
  int b = 0;
  while ( n > 1 ) {
    int h = n / 2;
    int t = A[b+h];
    __builtin_prefetch(&A[b + h/2]);      // next probe if the key is in the lower half
    __builtin_prefetch(&A[b + h + h/2]);  // next probe if it is in the upper half
    b = (t < key) ? b+h : b;
    n = n - h;
  }
  return b;
}

int search ( int A[], int n, int key ) {
  int b = 0;
  while ( n > 1 ) {
    int h = n / 2;
    int t = A[b+h];
    __builtin_prefetch(&A[b + h/4]);          // the probes 2 iterations later:
    __builtin_prefetch(&A[b + h/2 + h/4]);    // one for each of the 4 paths
    __builtin_prefetch(&A[b + h + h/4]);
    __builtin_prefetch(&A[b + h + h/2 + h/4]);
    b = (t < key) ? b+h : b;
    n = n - h;
  }
  return b;
}
